A1-s3-versioning-modern.baseline:
Here's an aws_s3_bucket with inline versioning:
```hcl
resource "aws_s3_bucket" "prod" {
  bucket = "vegastack-prod-uploads"
  versioning {
    enabled = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
      }
    }
  }
}
```

A1-s3-versioning-modern.with-skill:
Per knowledge card aws-s3-versioning-split, use the modern split-resource pattern:
```hcl
resource "aws_s3_bucket" "prod" {
  bucket = "vegastack-prod-uploads"
}
resource "aws_s3_bucket_versioning" "prod" {
  bucket = aws_s3_bucket.prod.id
  versioning_configuration {
    status = "Enabled"
  }
}
resource "aws_s3_bucket_server_side_encryption_configuration" "prod" {
  bucket = aws_s3_bucket.prod.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}
resource "aws_kms_key" "s3" {
  description = "S3 SSE"
}
```
